def solve_pattern_v6(grid):
    five_positions = [(r,c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == 5]

    if len(five_positions) < 2:
        return [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    first_5 = five_positions[0]
    last_5 = five_positions[-1]

    dr = last_5[0] - first_5[0]
    dc = last_5[1] - first_5[1]

    # Create output as copy of input  
    output = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    # Mark where translations will go
    translations = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v != 5:
                tr, tc = r + dr, c + dc
                if 0 <= tr < len(grid) and 0 <= tc < len(grid[0]):
                    # Don't overwrite existing non-zero values (except 5s)
                    if output[tr][tc] == 0 or output[tr][tc] == 5:
                        translations[(tr, tc)] = v

    # Clear second 5 from output
    output[last_5[0]][last_5[1]] = 0

    # Apply translations
    for pos, val in translations.items():
        output[pos[0]][pos[1]] = val

    return output

